"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["32427"],{33747(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.bloco_exigido_ausente","status":422,"titulo":"Falta um bloco que a finalidade exige"},"descricao":{"codigo":"uniplus.estrutura_formulario.bloco_exigido_ausente","requisitos":[],"oQueAconteceu":["As etapas de um formul\xe1rio, de qualquer finalidade (inscri\xe7\xe3o, pedido de isen\xe7\xe3o da taxa ou habilita\xe7\xe3o), precisam trazer o bloco de sistema `REVISAO_E_ACEITE`, em que o candidato revisa as respostas e aceita o envio. As etapas enviadas n\xe3o o trazem; a lista de etapas vazia cai aqui tamb\xe9m. A mensagem \xe9 \\"O formul\xe1rio precisa do bloco REVISAO_E_ACEITE.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `etapas`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. O bloco n\xe3o \xe9 acrescentado pelo sistema: ele precisa vir nas etapas enviadas.","A estrutura das etapas s\xf3 \xe9 conferida quando todas as etapas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada etapa \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as etapas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as etapas s\xf3 depois que a estrutura das etapas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Acrescente \xe0s etapas uma etapa com `tipo` igual a `BLOCO` e `bloco` igual a `REVISAO_E_ACEITE`, com a maior `ordem` do formul\xe1rio, porque a revis\xe3o e aceite \xe9 sempre a \xfaltima etapa. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);